#!/bin/bash
# A-Factor STEM Studio — new site icon (crest logo)
# Run inside af2s/ (the project ROOT, not inside patches/):
#     bash patches/patch-v73-site-icon.sh
#
# Replaces the browser-tab icon and adds the modern icon set, using the crest
# logo you uploaded. This writes THREE files via Next.js's App Router "special
# file" conventions, which are auto-detected with ZERO code changes needed:
#
#   src/app/favicon.ico    ->  served at /favicon.ico            (classic tab icon)
#   src/app/icon.png       ->  served at /icon.png, <link rel="icon"> auto-added
#   src/app/apple-icon.png ->  served at /apple-icon.png, <link rel="apple-touch-icon"> auto-added
#
# WHY THE LOGO WAS RE-CROPPED
#   Your uploaded logo has the crest sitting inside a wide decorative navy ring
#   and gold laurel wreath. At real favicon sizes (browsers mostly show 16x16
#   or 32x32 in an actual tab) that outer ring ate most of the pixel budget and
#   the crest itself became an unreadable blur — I checked this by rendering
#   the untouched logo at 16/32/48px before doing anything else. So the crest
#   here is cropped in tighter (dropping most of the outer ring, keeping a
#   sliver of the gold trim) so the shield and lettering actually read at
#   real tab size. The full, uncropped logo is untouched anywhere else you
#   might use it (letterhead, the About page, etc.) — this patch only touches
#   the three tab/home-screen icon files above.
#
# WHY apple-icon.png HAS A SOLID BACKGROUND, NOT A TRANSPARENT ONE
#   iOS applies its own rounded-corner mask to home-screen icons and can
#   render transparent areas as solid black, so that file uses a solid fill
#   in the crest's own navy (#12335A) instead of a transparent circle.
#
# This is a pure add/replace of three files — nothing else in the project is
# touched, and there is nothing to make idempotent (re-running just writes
# the same three files again).

set -e

if [ ! -f package.json ] || [ ! -d src ]; then
  echo "ERROR: run this from your project root (the folder containing package.json and src/),"
  echo "       e.g.   cd af2s   then   bash patches/patch-v73-site-icon.sh"
  exit 1
fi
if ! command -v base64 >/dev/null 2>&1; then
  echo "ERROR: the 'base64' command was not found on your PATH. It ships with Git Bash by"
  echo "       default, so this is unusual — try running this from Git Bash specifically."
  exit 1
fi

echo "Applying site icon patch..."
mkdir -p src/app

echo "  writing src/app/favicon.ico"
cat > /tmp/_icon_b64.txt << 'B64EOF'

B64EOF
base64 -d /tmp/_icon_b64.txt > src/app/favicon.ico
rm -f /tmp/_icon_b64.txt

echo "  writing src/app/icon.png"
cat > /tmp/_icon_b64.txt << 'B64EOF'

B64EOF
base64 -d /tmp/_icon_b64.txt > src/app/icon.png
rm -f /tmp/_icon_b64.txt

echo "  writing src/app/apple-icon.png"
cat > /tmp/_icon_b64.txt << 'B64EOF'

B64EOF
base64 -d /tmp/_icon_b64.txt > src/app/apple-icon.png
rm -f /tmp/_icon_b64.txt

echo ""
echo "Done. New icon files:"
echo "  src/app/favicon.ico   (multi-resolution: 16/24/32/48/64/128px)"
echo "  src/app/icon.png      (256px, modern browsers)"
echo "  src/app/apple-icon.png (180px, iOS/Android add-to-home-screen)"
echo ""
echo "Rebuild and hard-refresh to see it:"
echo "  bash -c \"rm -rf .next\""
echo "  npm run dev --webpack"
echo "  then Ctrl+Shift+R in the browser (favicons are cached aggressively)"
